class PcmCaptureProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    // nativeSR is passed via processorOptions from the main thread
    const nativeSR = (options && options.processorOptions && options.processorOptions.nativeSR)
      ? options.processorOptions.nativeSR
      : sampleRate;  // fallback: AudioWorkletGlobalScope.sampleRate

    this._ratio = nativeSR / 16000;
    this._fracPos = 0;          // fractional sample position (nearest-neighbor state)
    this._buf = new Int16Array(1536);
    this._bufPos = 0;
  }

  process(inputs) {
    const input = inputs[0];
    if (!input || !input[0]) return true;
    const ch = input[0];                 // mono; first channel

    for (let i = 0; i < ch.length; i++) {
      // nearest-neighbor: advance by ratio each input sample
      this._fracPos += 1;
      if (this._fracPos >= this._ratio) {
        this._fracPos -= this._ratio;

        // clamp and convert float32 \u2192 int16
        const s = ch[i];
        const clamped = s < -1 ? -1 : (s > 1 ? 1 : s);
        this._buf[this._bufPos++] = clamped < 0
          ? Math.round(clamped * 0x8000)
          : Math.round(clamped * 0x7fff);

        if (this._bufPos >= 1536) {
          // transfer the full frame to main thread
          const out = this._buf.buffer.slice(0);
          this.port.postMessage(out, [out]);
          this._buf = new Int16Array(1536);
          this._bufPos = 0;
        }
      }
    }
    return true;
  }
}

